css:
.dcx,.dcx{margin:0;padding:0;background:#FFFFFF;font-family:'Plus Jakarta Sans',system-ui,sans-serif;color:#0B2018;-webkit-font-smoothing:antialiased}
.dcx a{color:#0B3B29;text-decoration:none}
.dcx a:hover{color:#0E8A52}
.dcx *:focus-visible{outline:2px solid #0E8A52;outline-offset:2px}
@media (max-width:1180px){.dcx [data-nx-nav]{display:none!important}
}
@media (max-width:1040px){.dcx [data-nx="hero"],.dcx [data-nx="manage"],.dcx [data-nx="trio"],.dcx [data-nx="tail"]{grid-template-columns:minmax(0,1fr)!important;gap:32px!important}
.dcx [data-nx="g4"]{grid-template-columns:repeat(2,minmax(0,1fr))!important}
}
@media (max-width:760px){.dcx [data-nx="g4"]{grid-template-columns:minmax(0,1fr)!important}
.dcx [data-nx="callshell"],.dcx [data-nx="appshell"]{grid-template-columns:minmax(0,1fr)!important}
.dcx [data-nx="appside"]{display:none!important}
.dcx [data-nx="tiles"]{grid-template-columns:repeat(2,minmax(0,1fr))!important}
.dcx [data-nx="confrow"]{grid-template-columns:minmax(0,1.2fr) minmax(0,1fr)!important}
.dcx [data-nx="confrow"] [data-nx="hide-sm"]{display:none!important}
.dcx section > div{padding-left:18px!important;padding-right:18px!important}
}

.dch-654ae64e:hover{background:#082C1F !important;color:#FFFFFF !important}
